using System.Runtime.InteropServices;
using System.ServiceProcess;
namespace Nexora.Remote;

public static class ServiceRegistration
{
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern IntPtr OpenSCManager(string? machine, string? database, uint access);
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern IntPtr CreateService(IntPtr scm, string name, string display, uint access, uint type, uint start, uint error, string path, string? group, IntPtr tag, string? dependencies, string? user, string? password);
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern IntPtr OpenService(IntPtr scm, string name, uint access);
    [DllImport("advapi32.dll", SetLastError = true)] static extern bool DeleteService(IntPtr service);
    [DllImport("advapi32.dll")] static extern bool CloseServiceHandle(IntPtr handle);
    public static void Install() { if (!MachineIdentity.IsAdministrator) throw new UnauthorizedAccessException(); string exe = Environment.ProcessPath!; string programFiles = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles) + Path.DirectorySeparatorChar; if (!Path.GetFullPath(exe).StartsWith(programFiles, StringComparison.OrdinalIgnoreCase)) throw new UnauthorizedAccessException("Service executable must reside in protected Program Files"); for (DirectoryInfo? d = new(Path.GetDirectoryName(exe)!); d != null && d.FullName.Length >= programFiles.Length; d = d.Parent) if ((d.Attributes & FileAttributes.ReparsePoint) != 0) throw new UnauthorizedAccessException("Reparse points rejected"); IntPtr scm = OpenSCManager(null, null, 2); if (scm == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error()); try { var handle = CreateService(scm, "NexoraRemote", "NEXORA Remote Agent", 0xF01FF, 0x10, 2, 1, "\"" + exe + "\" --service", null, IntPtr.Zero, null, null, null); if (handle == IntPtr.Zero) { int error = Marshal.GetLastWin32Error(); if (error != 1073) throw new System.ComponentModel.Win32Exception(error); using var registration = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\NexoraRemote"); string expected = "\"" + exe + "\" --service"; if (!string.Equals(registration?.GetValue("ImagePath") as string, expected, StringComparison.OrdinalIgnoreCase)) throw new UnauthorizedAccessException("Existing service belongs to a different executable; refusing to modify it"); } else CloseServiceHandle(handle); } finally { CloseServiceHandle(scm); } using var recovery = System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(Environment.SystemDirectory, "sc.exe")) { UseShellExecute = false, CreateNoWindow = true, ArgumentList = { "failure", "NexoraRemote", "reset=", "86400", "actions=", "restart/5000/restart/15000/restart/30000" } })!; recovery.WaitForExit(); if (recovery.ExitCode != 0) throw new InvalidOperationException("Service recovery configuration failed"); }
    public static void Stop() { using var service = new ServiceController("NexoraRemote"); try { if (service.Status != ServiceControllerStatus.Stopped) { service.Stop(); service.WaitForStatus(ServiceControllerStatus.Stopped, TimeSpan.FromSeconds(25)); } } catch (InvalidOperationException ex) when (ex.InnerException is System.ComponentModel.Win32Exception w && w.NativeErrorCode == 1060) { } }
    public static void Remove() { if (!MachineIdentity.IsAdministrator) throw new UnauthorizedAccessException(); Stop(); IntPtr scm = OpenSCManager(null, null, 1); if (scm == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error()); try { var handle = OpenService(scm, "NexoraRemote", 0x10000); if (handle == IntPtr.Zero) { if (Marshal.GetLastWin32Error() != 1060) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error()); return; } try { if (!DeleteService(handle)) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error()); } finally { CloseServiceHandle(handle); } } finally { CloseServiceHandle(scm); } }
}
